# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _month_mult(m: int) -> float:
    return FESTIVE_MONTHS.get(m, 1.0)


def _random_date_arr(start: date, end: date, size: int) -> np.ndarray:
    delta = (end - start).days
    offsets = RNG.integers(0, delta + 1, size=size)
    return np.array([start + timedelta(days=int(d)) for d in offsets])


def _wchoice(choices: list, weights: list | np.ndarray, size: int) -> np.ndarray:
    w = np.asarray(weights, dtype=float)
    w /= w.sum()
    idx = RNG.choice(len(choices), size=size, p=w)
    return np.array(choices)[idx]


def _miss(series: pd.Series, rate: float) -> pd.Series:
    """Introduce NaN at *rate* fraction of rows."""
    mask = RNG.random(len(series)) < rate
    s = series.copy().astype(object)
    s[mask] = np.nan
    return s


def _dupes(df: pd.DataFrame, n: int) -> pd.DataFrame:
    """Append n duplicate rows."""
    d = df.sample(n=n, random_state=RANDOM_SEED, replace=True)
    return pd.concat([df, d], ignore_index=True)


def _save(df: pd.DataFrame, path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    df.to_csv(path, index=False)
    print(f"    saved  {path.relative_to(REPO_ROOT)}  ({len(df):,} rows, {len(df.columns)} cols)")


# ---------------------------------------------------------------------------
# 1. Customers
# ---------------------------------------------------------------------------

def generate_customers(n: int) -> pd.DataFrame:
    print(f"  Generating {n:,} customers ...")

    city_idx = RNG.choice(len(INDIAN_CITIES_STATES), size=n, p=CITY_WEIGHTS)
    cities = [INDIAN_CITIES_STATES[i][0] for i in city_idx]
    states = [INDIAN_CITIES_STATES[i][1] for i in city_idx]
    segments = _wchoice(CUSTOMER_SEGMENTS, SEGMENT_WEIGHTS, n)

    reg_start = START_DATE - timedelta(days=180)
    reg_dates = _random_date_arr(reg_start, END_DATE, n)
    ages = RNG.integers(18, 66, size=n)

    fn_idx = RNG.integers(0, len(FIRST_NAMES), size=n)
    ln_idx = RNG.integers(0, len(LAST_NAMES), size=n)
    fnames = np.array(FIRST_NAMES)[fn_idx]
    lnames = np.array(LAST_NAMES)[ln_idx]

    customer_ids = [f"CUST{i+1:06d}" for i in range(n)]
    emails = [f"{fn.lower()}.{ln.lower()}{i+1}@example.com"
              for i, (fn, ln) in enumerate(zip(fnames, lnames))]
    phones = [f"+91{int(RNG.integers(7000000000, 9999999999)):010d}" for _ in range(n)]

    df = pd.DataFrame({
        "customer_id": customer_ids,
        "first_name": fnames,
        "last_name": lnames,
        "email": emails,
        "phone": phones,
        "age": ages,
        "city": cities,
        "state": states,
        "customer_segment": segments,
        "registration_date": reg_dates,
        "is_active": RNG.random(n) > 0.08,
    })

    # --- Intentional data-quality issues ---
    df["phone"] = _miss(df["phone"], 0.03)           # ~3% missing phones
    df["age"] = _miss(df["age"], 0.02)               # ~2% missing age
    bad_seg = RNG.random(n) < 0.01                   # ~1% lowercase segment
    df.loc[bad_seg, "customer_segment"] = df.loc[bad_seg, "customer_segment"].str.lower()
    bad_dt = RNG.random(n) < 0.002                   # ~0.2% future date
    df.loc[bad_dt, "registration_date"] = date(2099, 1, 1)
    df = _dupes(df, max(1, int(n * 0.002)))          # ~0.2% dupes
    return df


# ---------------------------------------------------------------------------
# 2. Products
# ---------------------------------------------------------------------------

def generate_products(n: int = N_PRODUCTS) -> pd.DataFrame:
    print(f"  Generating {n} products ...")

    categories = _wchoice(PRODUCT_CATEGORIES, CATEGORY_WEIGHTS, n)
    product_ids = [f"PROD{i+1:04d}" for i in range(n)]
    names, prices, costs, cat_list = [], [], [], []

    for i, cat in enumerate(categories):
        lo, hi = CATEGORY_BASE_PRICES[cat]
        price = round(float(RNG.uniform(lo, hi)), 2)
        cost = round(price * float(RNG.uniform(0.40, 0.72)), 2)
        brand = BRANDS[i % len(BRANDS)]
        templates = PRODUCT_NAME_TEMPLATES.get(cat, ["Item {n}"])
        tmpl = templates[i % len(templates)]
        suffix = int(RNG.integers(1, 999))
        names.append(f"{brand} {tmpl.replace('{n}', str(suffix))}")
        prices.append(price)
        costs.append(cost)
        cat_list.append(cat)

    df = pd.DataFrame({
        "product_id": product_ids,
        "product_name": names,
        "category": cat_list,
        "price": prices,
        "cost": costs,
        "brand": [BRANDS[i % len(BRANDS)] for i in range(n)],
        "is_active": RNG.random(n) > 0.05,
        "launch_date": _random_date_arr(START_DATE - timedelta(days=365), END_DATE, n),
    })

    # --- Data-quality issues ---
    bad_cat = RNG.random(n) < 0.015                  # ~1.5% uppercase category
    df.loc[bad_cat, "category"] = df.loc[bad_cat, "category"].str.upper()
    outlier = RNG.random(n) < 0.005                  # ~0.5% price x100
    df.loc[outlier, "price"] = df.loc[outlier, "price"] * 100
    df["cost"] = _miss(df["cost"], 0.02)             # ~2% missing cost
    df = _dupes(df, max(1, int(n * 0.01)))           # ~1% dupes
    return df


# ---------------------------------------------------------------------------
# 3. Orders
# ---------------------------------------------------------------------------

def _day_weights() -> tuple[list[date], np.ndarray]:
    """Per-day sampling weights with seasonality + festive spikes."""
    dates: list[date] = []
    ws: list[float] = []
    cur = START_DATE
    while cur <= END_DATE:
        dow_factor = 1.15 if cur.weekday() >= 5 else 1.0
        ws.append(_month_mult(cur.month) * dow_factor)
        dates.append(cur)
        cur += timedelta(days=1)
    w = np.array(ws, dtype=float)
    w /= w.sum()
    return dates, w


def generate_orders(n: int, customer_ids: list[str], product_df: pd.DataFrame) -> pd.DataFrame:
    print(f"  Generating {n:,} orders ...")

    dates, dw = _day_weights()
    day_idx = RNG.choice(len(dates), size=n, p=dw)
    order_dates = np.array([dates[i] for i in day_idx])

    # Power-buyer skew: top 20% of customers get 3x weight
    cw = np.ones(len(customer_ids), dtype=float)
    cw[: len(customer_ids) // 5] *= 3
    cw /= cw.sum()
    cust_idx = RNG.choice(len(customer_ids), size=n, p=cw)
    sampled_cust = np.array(customer_ids)[cust_idx]

    # Product weights by category demand
    pw = np.array([CATEGORY_ORDER_DEMAND.get(c, 1) for c in product_df["category"]], dtype=float)
    pw /= pw.sum()
    prod_idx = RNG.choice(len(product_df), size=n, p=pw)
    sprods = product_df.iloc[prod_idx].reset_index(drop=True)

    quantities = RNG.integers(1, 6, size=n)
    unit_prices = np.round(sprods["price"].to_numpy(dtype=float) * RNG.uniform(0.95, 1.05, size=n), 2)

    # Higher discounts during festive months
    disc_pct = np.array([
        float(RNG.uniform(0.05, 0.30)) if _month_mult(d.month) > 1.2
        else float(RNG.uniform(0.0, 0.15))
        for d in order_dates
    ])
    disc_amt = np.round(unit_prices * quantities * disc_pct, 2)
    total = np.round(unit_prices * quantities - disc_amt, 2)
    statuses = _wchoice(ORDER_STATUSES, ORDER_STATUS_WEIGHTS, n)
    order_ids = [f"ORD{i+1:07d}" for i in range(n)]

    city_idx = RNG.choice(len(INDIAN_CITIES_STATES), size=n)
    df = pd.DataFrame({
        "order_id": order_ids,
        "customer_id": sampled_cust,
        "product_id": sprods["product_id"].to_numpy(),
        "order_date": order_dates,
        "quantity": quantities,
        "unit_price": unit_prices,
        "discount_amount": disc_amt,
        "total_amount": total,
        "order_status": statuses,
        "city": [INDIAN_CITIES_STATES[i][0] for i in city_idx],
        "state": [INDIAN_CITIES_STATES[i][1] for i in city_idx],
    })

    # --- Data-quality issues ---
    df["customer_id"] = _miss(df["customer_id"], 0.015)  # ~1.5% orphan orders
    bad_prod = RNG.random(n) < 0.01
    df.loc[bad_prod, "product_id"] = "PROD9999"          # ~1% invalid product FK
    neg = RNG.random(n) < 0.002
    df.loc[neg, "total_amount"] = -df.loc[neg, "total_amount"]  # ~0.2% negative amount
    df["order_status"] = _miss(df["order_status"], 0.005)
    bad_dt = RNG.random(n) < 0.001
    df.loc[bad_dt, "order_date"] = date(1970, 1, 1)      # ~0.1% epoch date
    df = _dupes(df, max(1, int(n * 0.003)))              # ~0.3% dupes
    return df


# ---------------------------------------------------------------------------
# 4. Payments
# ---------------------------------------------------------------------------

def generate_payments(orders_df: pd.DataFrame) -> pd.DataFrame:
    print(f"  Generating payments ...")

    # ~3% of orders have no payment (abandoned / failed checkout)
    mask = RNG.random(len(orders_df)) > 0.03
    pay_df = orders_df[mask].copy()
    n = len(pay_df)

    methods = _wchoice(PAYMENT_METHODS, PAYMENT_METHOD_WEIGHTS, n)
    pay_dates = np.array([
        d + timedelta(days=int(RNG.integers(0, 3)))
        for d in pay_df["order_date"].to_numpy()
    ])
    statuses = _wchoice(
        ["success", "failed", "pending", "refunded"],
        [0.90, 0.03, 0.02, 0.05], n,
    )
    payment_ids = [f"PAY{i+1:07d}" for i in range(n)]

    df = pd.DataFrame({
        "payment_id": payment_ids,
        "order_id": pay_df["order_id"].to_numpy(),
        "payment_method": methods,
        "payment_date": pay_dates,
        "amount": pay_df["total_amount"].to_numpy(),
        "payment_status": statuses,
        "transaction_ref": [f"TXN{int(RNG.integers(100000000, 999999999))}" for _ in range(n)],
    })

    # --- Data-quality issues ---
    df["payment_method"] = _miss(df["payment_method"], 0.02)
    amt_mask = RNG.random(n) < 0.005
    n_bad = int(amt_mask.sum())
    if n_bad:
        scales = RNG.uniform(0.1, 10.0, size=n_bad)
        df.loc[amt_mask, "amount"] = np.round(
            df.loc[amt_mask, "amount"].to_numpy(dtype=float) * scales, 2
        )
    df = _dupes(df, max(1, int(n * 0.002)))
    return df


# ---------------------------------------------------------------------------
# 5. Delivery
# ---------------------------------------------------------------------------

def generate_delivery(orders_df: pd.DataFrame) -> pd.DataFrame:
    print(f"  Generating delivery records ...")

    # ~2% no delivery record (digital goods / pickup / data gap)
    mask = RNG.random(len(orders_df)) > 0.02
    del_df = orders_df[mask].copy()
    n = len(del_df)

    couriers = _wchoice(COURIER_PARTNERS, [0.25, 0.25, 0.20, 0.10, 0.10, 0.10], n)
    est_dates = np.array([
        d + timedelta(days=int(RNG.integers(2, 8)))
        for d in del_df["order_date"].to_numpy()
    ])
    outcomes = _wchoice(
        ["on_time", "early", "delayed", "not_delivered"],
        [0.75, 0.05, 0.15, 0.05], n,
    )

    actual_dates, del_statuses, del_days = [], [], []
    o_dates = del_df["order_date"].to_numpy()
    o_statuses = del_df["order_status"].to_numpy()

    for i, (est, outcome) in enumerate(zip(est_dates, outcomes)):
        o_date = o_dates[i]
        o_status = str(o_statuses[i]) if o_statuses[i] is not None else ""

        if outcome == "on_time":
            actual = est
        elif outcome == "early":
            actual = est - timedelta(days=int(RNG.integers(1, 3)))
        elif outcome == "delayed":
            actual = est + timedelta(days=int(RNG.integers(1, 15)))
        else:
            actual = None

        actual_dates.append(actual)
        del_days.append((actual - o_date).days if actual is not None else None)

        if o_status == "cancelled":
            del_statuses.append("cancelled")
        elif outcome == "not_delivered":
            del_statuses.append("in_transit")
        elif outcome == "delayed":
            del_statuses.append("delayed")
        else:
            del_statuses.append("delivered")

    delivery_ids = [f"DEL{i+1:07d}" for i in range(n)]
    df = pd.DataFrame({
        "delivery_id": delivery_ids,
        "order_id": del_df["order_id"].to_numpy(),
        "courier_partner": couriers,
        "estimated_delivery_date": est_dates,
        "actual_delivery_date": actual_dates,
        "delivery_status": del_statuses,
        "delivery_days": del_days,
    })

    # --- Data-quality issues ---
    df["courier_partner"] = _miss(df["courier_partner"], 0.02)
    df = _dupes(df, max(1, int(n * 0.003)))
    return df


# ---------------------------------------------------------------------------
# 6. Marketing campaigns
# ---------------------------------------------------------------------------

def generate_marketing_campaigns(customer_ids: list[str], orders_df: pd.DataFrame) -> pd.DataFrame:
    n = int(len(customer_ids) * 1.6)
    print(f"  Generating {n:,} marketing campaign events ...")

    valid_n = int(n * 0.90)
    invalid_n = n - valid_n
    sampled = list(RNG.choice(customer_ids, size=valid_n, replace=True))
    invalid = [f"CUST{int(RNG.integers(900000, 999999)):06d}" for _ in range(invalid_n)]
    all_cust = sampled + invalid
    random.shuffle(all_cust)

    camp_dates = _random_date_arr(START_DATE, END_DATE, n)
    types = _wchoice(CAMPAIGN_TYPES, [0.25, 0.20, 0.20, 0.20, 0.15], n)
    channels = _wchoice(CAMPAIGN_CHANNELS, [0.20, 0.20, 0.15, 0.20, 0.15, 0.10], n)

    ctrs = np.array([
        float(RNG.uniform(*CTR_BY_CHANNEL.get(ch, (0.01, 0.05))))
        for ch in channels
    ])
    converted = RNG.random(n) < (ctrs * 0.30)
    spend = np.round(RNG.uniform(5, 500, size=n), 2)
    campaign_ids = [f"CMP{i+1:07d}" for i in range(n)]

    df = pd.DataFrame({
        "campaign_id": campaign_ids,
        "customer_id": all_cust,
        "campaign_type": types,
        "channel": channels,
        "campaign_date": camp_dates,
        "click_through_rate": np.round(ctrs, 4),
        "converted": converted,
        "spend_inr": spend,
    })

    # --- Data-quality issues ---
    df["channel"] = _miss(df["channel"], 0.02)
    df["spend_inr"] = _miss(df["spend_inr"], 0.03)
    df = _dupes(df, max(1, int(n * 0.005)))
    return df


# ---------------------------------------------------------------------------
# Verification / summary
# ---------------------------------------------------------------------------

def verify_and_summarise(datasets: dict[str, pd.DataFrame]) -> None:
    print("\n" + "=" * 70)
    print("VERIFICATION SUMMARY")
    print("=" * 70)

    cust = datasets.get("customers", pd.DataFrame())
    prod = datasets.get("products", pd.DataFrame())
    ord_ = datasets.get("orders", pd.DataFrame())
    pay  = datasets.get("payments", pd.DataFrame())
    dlv  = datasets.get("delivery", pd.DataFrame())
    cmp  = datasets.get("marketing_campaigns", pd.DataFrame())

    # Row counts
    print("\n[Row counts]")
    for name, df in datasets.items():
        print(f"  {name:<25} {len(df):>8,} rows  | {len(df.columns)} columns")

    # Column names
    print("\n[Columns]")
    for name, df in datasets.items():
        print(f"  {name}: {list(df.columns)}")

    # Date ranges
    print("\n[Date ranges]")
    for name, col in [
        ("orders", "order_date"), ("customers", "registration_date"),
        ("payments", "payment_date"), ("delivery", "actual_delivery_date"),
        ("marketing_campaigns", "campaign_date"),
    ]:
        df = datasets.get(name, pd.DataFrame())
        if col in df.columns:
            vals = pd.to_datetime(df[col], errors="coerce").dropna()
            if not vals.empty:
                print(f"  {name}.{col}: {vals.min().date()} -> {vals.max().date()}")

    # Duplicates
    print("\n[Duplicate rows]")
    for name, df in datasets.items():
        nd = df.duplicated().sum()
        print(f"  {name:<25} {nd:>6,} dupes ({100*nd/max(len(df),1):.2f}%)")

    # Missing values
    print("\n[Missing values - top 5 columns per table]")
    for name, df in datasets.items():
        m = df.isnull().sum()
        m = m[m > 0].sort_values(ascending=False).head(5)
        if not m.empty:
            parts = ", ".join(f"{c}={v}" for c, v in m.items())
            print(f"  {name}: {parts}")
        else:
            print(f"  {name}: none")

    # Reference consistency
    print("\n[FK / reference consistency]")
    if not (ord_.empty or cust.empty):
        valid_c = set(cust["customer_id"].dropna())
        orphan_o_c = set(ord_["customer_id"].dropna()) - valid_c
        print(f"  orders -> customers:   {len(orphan_o_c):>5,} invalid customer_id refs (intentional ~1.5% missing + dupes may add more)")
    if not (ord_.empty or prod.empty):
        valid_p = set(prod["product_id"].dropna())
        orphan_o_p = set(ord_["product_id"].dropna()) - valid_p
        print(f"  orders -> products:   {len(orphan_o_p):>5,} invalid product_id refs (expected: only PROD9999)")
    if not (pay.empty or ord_.empty):
        valid_o = set(ord_["order_id"].dropna())
        orphan_pay = set(pay["order_id"].dropna()) - valid_o
        print(f"  payments -> orders:   {len(orphan_pay):>5,} invalid order_id refs")
    if not (dlv.empty or ord_.empty):
        orphan_dlv = set(dlv["order_id"].dropna()) - valid_o
        print(f"  delivery -> orders:   {len(orphan_dlv):>5,} invalid order_id refs")
    if not (cmp.empty or cust.empty):
        orphan_cmp = set(cmp["customer_id"].dropna()) - valid_c
        print(f"  campaigns -> customers:{len(orphan_cmp):>5,} invalid customer_id refs (~10% intentional)")

    # Summary of intentional issues
    print("\n[Intentional data-quality issues introduced]")
    rows = [
        ("Missing values",
         "customers.phone ~3%, age ~2%; orders.customer_id ~1.5%, order_status ~0.5%;\n"
         "    products.cost ~2%; payments.payment_method ~2%;\n"
         "    delivery.courier_partner ~2%; campaigns.channel ~2%, spend_inr ~3%"),
        ("Duplicate rows",
         "customers ~0.2%, products ~1%, orders ~0.3%,\n"
         "    payments ~0.2%, delivery ~0.3%, campaigns ~0.5%"),
        ("Inconsistent capitalisation",
         "customers.customer_segment ~1% lowercased;\n"
         "    products.category ~1.5% uppercased"),
        ("Invalid dates",
         "customers.registration_date ~0.2% = 2099-01-01 (future);\n"
         "    orders.order_date ~0.1% = 1970-01-01 (epoch)"),
        ("Numerical outliers",
         "products.price ~0.5% x100; orders.total_amount ~0.2% negated;\n"
         "    payments.amount ~0.5% scaled 0.1-10x"),
        ("Invalid FK references",
         "orders.product_id ~1% = PROD9999 (non-existent);\n"
         "    campaigns.customer_id ~10% non-existent IDs"),
    ]
    for kind, detail in rows:
        print(f"  [{kind}]\n    {detail}")

    print("\n" + "=" * 70)


# ---------------------------------------------------------------------------
# Runner
# ---------------------------------------------------------------------------

def run_generation(
    n_customers: int,
    n_orders: int,
    out_dir: Path,
    label: str,
) -> dict[str, pd.DataFrame]:
    print(f"\n{'='*70}")
    print(f"  Dataset: {label}  |  customers={n_customers:,}  orders={n_orders:,}")
    print(f"  Output:  {out_dir}")
    print(f"{'='*70}")

    customers_df  = generate_customers(n_customers)
    products_df   = generate_products(N_PRODUCTS)
    # Use clean IDs (no dupes/missing) as FK pool for orders
    clean_cids    = [f"CUST{i+1:06d}" for i in range(n_customers)]
    orders_df     = generate_orders(n_orders, clean_cids, products_df)
    payments_df   = generate_payments(orders_df)
    delivery_df   = generate_delivery(orders_df)
    campaigns_df  = generate_marketing_campaigns(clean_cids, orders_df)

    datasets: dict[str, pd.DataFrame] = {
        "customers":           customers_df,
        "products":            products_df,
        "orders":              orders_df,
        "payments":            payments_df,
        "delivery":            delivery_df,
        "marketing_campaigns": campaigns_df,
    }

    print(f"\n  Writing CSVs to {out_dir} ...")
    for name, df in datasets.items():
        _save(df, out_dir / f"{name}.csv")

    verify_and_summarise(datasets)
    return datasets


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def _args() -> argparse.Namespace:
    p = argparse.ArgumentParser(
        description="Generate synthetic e-commerce datasets for InsightForge AI."
    )
    g = p.add_mutually_exclusive_group()
    g.add_argument("--sample", action="store_true", help="Sample dataset only (fast).")
    g.add_argument("--both", action="store_true", help="Full + sample datasets.")
    return p.parse_args()


def main() -> None:
    args = _args()
    if args.sample:
        run_generation(N_CUSTOMERS_SAMPLE, N_ORDERS_SAMPLE, SAMPLE_DIR, "sample")
    elif args.both:
        run_generation(N_CUSTOMERS_FULL, N_ORDERS_FULL, RAW_DIR, "full")
        run_generation(N_CUSTOMERS_SAMPLE, N_ORDERS_SAMPLE, SAMPLE_DIR, "sample")
    else:
        run_generation(N_CUSTOMERS_FULL, N_ORDERS_FULL, RAW_DIR, "full")
    print("\nDone.")


if __name__ == "__main__":
    main()
